--[[
    HzReyzn Hub | PRISM LOADING
    Pantalla independiente inspirada en el video del usuario.

    USO EN STUDIO: LocalScript en StarterPlayer > StarterPlayerScripts.
    Para verla antes al entrar, el LocalScript puede ir en ReplicatedFirst.
    La animacion dura 5 s; a continuacion se desvanece durante 0.95 s.
    El porcentaje representa el tiempo de esta introduccion, no descargas.

    LOGO: incluye la imagen original, sin conexiones HTTP ni librerias externas.
    1. LogoAssetId, si lo configuras, tiene prioridad.
    2. Si existen writefile/getcustomasset, carga el original desde una cache local.
    3. En Studio/experiencias con EditableImage habilitado, reconstruye los pixeles.
    4. Si el entorno bloquea ambas rutas, muestra un titulo tipografico de respaldo.
       Para el logo exacto en ese caso, sube tu imagen a Roblox y coloca su ID abajo.

    El bloque de datos al final es tu imagen, NO codigo ofuscado.
    El script solo crea su interfaz. No cambia Lighting, personaje ni camara.
    Para conectar tu hub, utiliza OnComplete al final de CONFIG.
]]

local CONFIG = {
    Duration = 5,
    FadeOut = 0.95,
    LogoAssetId = "", -- Ejemplo: "rbxassetid://1234567890" (ID de imagen).
    Quality = "Auto", -- "Auto", "High" o "Low".
    RemoveDefaultRobloxLoading = false, -- Solo si lo colocas en ReplicatedFirst.
    OnComplete = function()
        -- Abre aqui tu interfaz principal cuando termine la introduccion.
    end,
}

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ContentProvider = game:GetService("ContentProvider")
local UserInputService = game:GetService("UserInputService")
local AssetService = game:GetService("AssetService")

local C = {
    black = Color3.fromRGB(0, 0, 0),
    violet = Color3.fromRGB(137, 59, 255),
    deep = Color3.fromRGB(68, 17, 178),
    magenta = Color3.fromRGB(252, 55, 236),
    cyan = Color3.fromRGB(46, 220, 255),
    ice = Color3.fromRGB(206, 243, 255),
    white = Color3.fromRGB(248, 236, 255),
    muted = Color3.fromRGB(170, 151, 196),
}

local loadOriginalBytes, loadPixelBytes -- Datos incluidos al final del archivo.
local GUI_NAME = "HzReyzn_PrismLoading"
local TWO_PI = math.pi * 2

local function smooth(x)
    x = math.clamp(x, 0, 1)
    return x * x * (3 - 2 * x)
end

local function sequence(points)
    local result = {}
    for _, p in ipairs(points) do
        result[#result + 1] = NumberSequenceKeypoint.new(p[1], p[2])
    end
    return NumberSequence.new(result)
end

local function colorSequence(colors)
    local result = {}
    for i, c in ipairs(colors) do
        result[i] = ColorSequenceKeypoint.new((i - 1) / (#colors - 1), c)
    end
    return ColorSequence.new(result)
end

local COLOR_FLOW = colorSequence({C.cyan, C.violet, C.magenta, C.ice})
local SOFT_LINE = sequence({{0, 1}, {0.23, 0.6}, {0.5, 0}, {0.77, 0.6}, {1, 1}})
local INWARD = sequence({{0, 0}, {0.12, 0.36}, {0.37, 0.76}, {0.68, 0.95}, {1, 1}})

local function make(className, props, parent)
    local object = Instance.new(className)
    for key, value in pairs(props) do object[key] = value end
    object.Parent = parent
    return object
end

-- Decodificador de datos, no ejecuta el contenido de la imagen.
local function base64Decode(encoded, alive)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i = 1, #alphabet do lookup[string.byte(alphabet, i)] = i - 1 end
    local padding = encoded:sub(-2) == "==" and 2 or (encoded:sub(-1) == "=" and 1 or 0)
    local length = #encoded / 4 * 3 - padding
    local output = buffer.create(length)
    local offset = 0
    for i = 1, #encoded, 4 do
        local a, b, c, d = string.byte(encoded, i, i + 3)
        local n = lookup[a] * 262144 + lookup[b] * 4096
            + (lookup[c] or 0) * 64 + (lookup[d] or 0)
        buffer.writeu8(output, offset, math.floor(n / 65536))
        if offset + 1 < length then buffer.writeu8(output, offset + 1, math.floor(n / 256) % 256) end
        if offset + 2 < length then buffer.writeu8(output, offset + 2, n % 256) end
        offset = offset + 3
        if i % 65536 == 1 and i > 1 then
            if not alive() then error("Loading cancelled") end
            task.wait()
        end
    end
    return output
end

-- QOI lossless: conserva los valores RGB del original. Dos mosaicos evitan
-- superar el limite de 1024 px por lado de EditableImage.
local function decodeLogoTiles(encoded, alive)
    local source = base64Decode(encoded, alive)
    local tileWidth, height = 768, 704
    local cropTop, sourceWidth, sourceHeight = 96, 1536, 864
    assert(buffer.readstring(source, 0, 4) == "qoif", "Invalid embedded logo")
    local tiles = {buffer.create(tileWidth * height * 4), buffer.create(tileWidth * height * 4)}
    local index = {}
    for i = 0, 63 do index[i] = {0, 0, 0, 0} end
    local r, g, b, a = 0, 0, 0, 255
    local cursor, run = 14, 0
    for pixel = 0, sourceWidth * sourceHeight - 1 do
        if run > 0 then
            run = run - 1
        else
            local op = buffer.readu8(source, cursor)
            cursor = cursor + 1
            if op == 254 then
                r, g, b = buffer.readu8(source, cursor), buffer.readu8(source, cursor + 1), buffer.readu8(source, cursor + 2)
                cursor = cursor + 3
            elseif op == 255 then
                r, g, b, a = buffer.readu8(source, cursor), buffer.readu8(source, cursor + 1), buffer.readu8(source, cursor + 2), buffer.readu8(source, cursor + 3)
                cursor = cursor + 4
            elseif op < 64 then
                local p = index[op]
                r, g, b, a = p[1], p[2], p[3], p[4]
            elseif op < 128 then
                r = (r + math.floor(op / 16) % 4 - 2) % 256
                g = (g + math.floor(op / 4) % 4 - 2) % 256
                b = (b + op % 4 - 2) % 256
            elseif op < 192 then
                local nextByte = buffer.readu8(source, cursor)
                cursor = cursor + 1
                local dg = op % 64 - 32
                r = (r + dg + math.floor(nextByte / 16) - 8) % 256
                g = (g + dg) % 256
                b = (b + dg + nextByte % 16 - 8) % 256
            else
                run = op % 64
            end
            local slot = (r * 3 + g * 5 + b * 7 + a * 11) % 64
            local p = index[slot]
            p[1], p[2], p[3], p[4] = r, g, b, a
        end
        local y = math.floor(pixel / sourceWidth) - cropTop
        if y >= 0 and y < height then
            local x = pixel % sourceWidth
            local tile = x < tileWidth and 1 or 2
            local offset = (y * tileWidth + x % tileWidth) * 4
            buffer.writeu32(tiles[tile], offset, r + g * 256 + b * 65536 + a * 16777216)
        end
        if pixel > 0 and pixel % (sourceWidth * 96) == 0 then
            if not alive() then error("Loading cancelled") end
            task.wait()
        end
    end
    return tiles, tileWidth, height
end

local function play()
    if not RunService:IsClient() then
        warn("HzReyzn: utiliza un LocalScript del cliente.")
        return false
    end
    local player = Players.LocalPlayer
    if not player then return false end
    local playerGui = player:WaitForChild("PlayerGui", 10)
    if not playerGui then return false end

    local old = playerGui:FindFirstChild(GUI_NAME)
    if old then
        local stop = old:FindFirstChild("StopLoading")
        if stop and stop:IsA("BindableEvent") then stop:Fire() end
        if old.Parent then old:Destroy() end
    end

    local S = {alive = true, completed = false, connections = {}, images = {}, fades = {}, time = 0}
    local gui = make("ScreenGui", {
        Name = GUI_NAME, IgnoreGuiInset = true, ResetOnSpawn = false,
        DisplayOrder = 10000, ZIndexBehavior = Enum.ZIndexBehavior.Global, Enabled = false,
    }, playerGui)
    pcall(function()
        gui.ScreenInsets = Enum.ScreenInsets.None
        gui.ClipToDeviceSafeArea = false
    end)

    local function cleanup(completed)
        if not S.alive then return end
        S.alive, S.completed = false, completed == true
        for _, connection in ipairs(S.connections) do connection:Disconnect() end
        gui:Destroy()
        for _, editable in ipairs(S.images) do pcall(function() editable:Destroy() end) end
        table.clear(S.connections)
        table.clear(S.images)
        table.clear(S.fades)
    end

    S.connections[#S.connections + 1] = gui.Destroying:Connect(function() cleanup(false) end)
    local stop = make("BindableEvent", {Name = "StopLoading"}, gui)
    S.connections[#S.connections + 1] = stop.Event:Connect(function() cleanup(false) end)

    local function paint(object, property, opacity, channel)
        local entry = {object = object, property = property, opacity = opacity, channel = channel or "fx", multiplier = 1, last = -1}
        object[property] = 1
        S.fades[#S.fades + 1] = entry
        return entry
    end

    local function frame(parent, name, position, size, color, opacity, z, channel)
        local object = make("Frame", {
            Name = name, Position = position, Size = size, BorderSizePixel = 0,
            BackgroundColor3 = color or C.black, BackgroundTransparency = 1, ZIndex = z or 2,
        }, parent)
        if opacity and opacity > 0 then paint(object, "BackgroundTransparency", opacity, channel) end
        return object
    end

    local function gradient(object, colors, transparency, rotation)
        return make("UIGradient", {Color = colors or COLOR_FLOW,
            Transparency = transparency or NumberSequence.new(0), Rotation = rotation or 0}, object)
    end

    local function line(parent, name, x1, y1, x2, y2, width, color, opacity, z, soft)
        local dx, dy = x2 - x1, y2 - y1
        local object = frame(parent, name, UDim2.fromOffset((x1 + x2) / 2, (y1 + y2) / 2),
            UDim2.fromOffset(math.sqrt(dx * dx + dy * dy), width), color, opacity, z)
        object.AnchorPoint = Vector2.new(0.5, 0.5)
        object.Rotation = math.deg(math.atan2(dy, dx))
        if soft then gradient(object, ColorSequence.new(color), SOFT_LINE) end
        return object
    end

    local function glow(parent, name, x, y, width, height, color, intensity, z, layers)
        local group = frame(parent, name, UDim2.fromOffset(x, y), UDim2.fromOffset(width, height), C.black, 0, z)
        group.AnchorPoint = Vector2.new(0.5, 0.5)
        for i = 1, layers do
            local k = 1 - (i - 1) / layers * 0.90
            local disk = frame(group, "Glow", UDim2.fromScale(0.5, 0.5), UDim2.fromScale(k, k), color,
                intensity * (0.18 + (i / layers) ^ 2 * 0.82), z)
            disk.AnchorPoint = Vector2.new(0.5, 0.5)
            make("UICorner", {CornerRadius = UDim.new(0.5, 0)}, disk)
        end
        return group
    end

    local function flare(parent, x, y, size, color, z)
        local group = frame(parent, "StarFlare", UDim2.fromOffset(x, y), UDim2.fromOffset(1, 1), C.black, 0, z)
        glow(group, "Halo", 0, 0, size * 1.7, size * 1.7, color, 0.035, z, 7)
        line(group, "HorizontalGlow", -size, 0, size, 0, 3.4, color, 0.38, z + 1, true)
        line(group, "Horizontal", -size, 0, size, 0, 1.1, C.white, 0.9, z + 2, true)
        line(group, "VerticalGlow", 0, -size * 0.62, 0, size * 0.62, 3, color, 0.38, z + 1, true)
        line(group, "Vertical", 0, -size * 0.62, 0, size * 0.62, 1.1, C.white, 0.85, z + 2, true)
        line(group, "Diagonal", -size * 0.23, size * 0.23, size * 0.23, -size * 0.23, 1, color, 0.7, z + 1, true)
        local core = frame(group, "Core", UDim2.fromOffset(0, 0), UDim2.fromOffset(3, 3), C.white, 0.95, z + 3)
        core.AnchorPoint, core.Rotation = Vector2.new(0.5, 0.5), 45
        return make("UIScale", {Scale = 1}, group), group
    end

    local ok, errorMessage = xpcall(function()
        local low = CONFIG.Quality == "Low" or (CONFIG.Quality == "Auto" and UserInputService.TouchEnabled)
        local random = Random.new(8273)
        local backdrop = frame(gui, "BlackBackdrop", UDim2.fromScale(0, 0), UDim2.fromScale(1, 1), C.black, 1, 1, "back")
        backdrop.Active = true
        local border = frame(backdrop, "NeonFrame", UDim2.fromOffset(22, 22), UDim2.new(1, -44, 1, -44), C.black, 0, 2)
        border.ClipsDescendants = true
        local perimeter = make("UIStroke", {Color = C.white, Thickness = 1.2, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, border)
        paint(perimeter, "Transparency", 0.6, "frame")
        local perimeterGradient = gradient(perimeter)

        local edgeGlows, edgeFrames = {}, {}
        local edgeDefinitions = {
            {UDim2.fromScale(0, 0), UDim2.fromScale(0.20, 1), 0, C.violet},
            {UDim2.fromScale(0.8, 0), UDim2.fromScale(0.20, 1), 180, C.magenta},
            {UDim2.fromScale(0, 0), UDim2.fromScale(1, 0.22), 90, C.violet},
            {UDim2.fromScale(0, 0.78), UDim2.fromScale(1, 0.22), 270, C.violet},
        }
        for i, def in ipairs(edgeDefinitions) do
            local edge = frame(border, "InwardLight" .. i, def[1], def[2], def[4], 0, 2)
            edgeFrames[i] = edge
            edgeGlows[i] = paint(edge, "BackgroundTransparency", 0.30, "frame")
            gradient(edge, ColorSequence.new(def[4]), INWARD, def[3])
        end

        local corners, travellers = {}, {}
        for i = 1, 4 do
            local holder = frame(border, "Corner" .. i, UDim2.fromOffset(0, 0), UDim2.fromOffset(80, 80), C.black, 0, 15)
            local color = i % 2 == 0 and C.cyan or C.magenta
            line(holder, "Upper", 15, 1, 68, 1, 2, color, 0.85, 15)
            line(holder, "Cut", 1, 15, 15, 1, 2, C.white, 0.82, 16)
            line(holder, "Side", 1, 15, 1, 68, 2, color, 0.85, 15)
            line(holder, "InsetUpper", 22, 8, 42, 8, 1, color, 0.42, 15)
            line(holder, "InsetSide", 8, 22, 8, 42, 1, color, 0.42, 15)
            corners[i] = holder
        end
        for i = 1, 2 do
            local scale, group = flare(border, 0, 0, 24, i == 1 and C.cyan or C.magenta, 17)
            travellers[i] = {group = group, scale = scale}
        end

        local stage = frame(backdrop, "Composition", UDim2.fromScale(0.5, 0.5), UDim2.fromOffset(1000, 620), C.black, 0, 3)
        stage.AnchorPoint = Vector2.new(0.5, 0.5)
        local stageScale = make("UIScale", {Scale = 1}, stage)

        -- Los haces y las orbitas son geometria GUI, no dependen de texturas externas.
        line(stage, "MagentaBeamGlow", -80, 180, 1080, 368, 8, C.magenta, 0.08, 9, true)
        line(stage, "MagentaBeam", -80, 180, 1080, 368, 1.1, C.magenta, 0.30, 9, true)
        line(stage, "VioletBeamGlow", -130, 296, 1130, 296, 9, C.violet, 0.07, 9, true)
        line(stage, "VioletBeam", -130, 296, 1130, 296, 1, C.violet, 0.26, 9, true)
        line(stage, "CyanBeam", 35, 370, 965, 210, 1, C.cyan, 0.13, 9, true)

        local logo = frame(stage, "Logo", UDim2.fromOffset(500, 253), UDim2.fromOffset(900, 412.5), C.black, 0, 6)
        logo.AnchorPoint = Vector2.new(0.5, 0.5)
        local logoScale = make("UIScale", {Scale = 1}, logo)
        local fallback = frame(logo, "TextFallback", UDim2.fromScale(0, 0), UDim2.fromScale(1, 1), C.black, 0, 6)
        local function title(text, y, size, font)
            local shadow = make("TextLabel", {
                Name = "TitleGlow", BackgroundTransparency = 1, Position = UDim2.new(0, 0, y, 4),
                Size = UDim2.fromScale(1, 0.3), Text = text, TextScaled = true, Font = font,
                TextColor3 = C.violet, TextStrokeColor3 = C.magenta, TextStrokeTransparency = 1, ZIndex = 6,
            }, fallback)
            paint(shadow, "TextTransparency", 0.30, "logo")
            paint(shadow, "TextStrokeTransparency", 0.38, "logo")
            local label = shadow:Clone()
            label.Name, label.Position, label.TextColor3, label.ZIndex = "Title", UDim2.fromScale(0, y), C.white, 7
            label.Parent = fallback
            paint(label, "TextTransparency", 1, "logo")
            gradient(label, colorSequence({C.ice, C.cyan, C.white, C.magenta}))
            make("UITextSizeConstraint", {MaxTextSize = size, MinTextSize = 12}, label)
            return label
        end
        title("HzReyzn", 0.22, 114, Enum.Font.GothamBlack)
        local hubTitle = title("HUB", 0.53, 65, Enum.Font.GothamBold)
        hubTitle.Size = UDim2.fromScale(1, 0.2)

        local aura = glow(stage, "VioletAura", 500, 439, 775, 174, C.violet, 0.026, 8, low and 15 or 23)
        glow(aura, "MagentaAura", 420, 96, 420, 56, C.magenta, 0.031, 8, low and 10 or 15)
        glow(stage, "CyanAura", 420, 461, 420, 46, C.cyan, 0.024, 8, low and 9 or 13)
        local auraScale = make("UIScale", {Scale = 1}, aura)
        line(stage, "AuraCoreGlow", 182, 461, 818, 461, 6, C.violet, 0.25, 9, true)
        line(stage, "AuraCore", 212, 461, 788, 461, 1.1, C.ice, 0.49, 10, true)

        local orbits = {}
        local segments = low and 22 or 32
        for orbit = 1, 2 do
            local items = {}
            for j = 1, segments do
                local item = line(stage, "EnergyArc", 0, 0, 1, 0, orbit == 1 and 1.35 or 0.9,
                    orbit == 1 and C.magenta or C.cyan, 0.1 + j / segments * 0.36, 9, false)
                items[j] = item
            end
            orbits[orbit] = items
        end

        local flares = {}
        local flareSpots = {{172, 194, 38, C.magenta}, {777, 180, 34, C.cyan}, {650, 339, 30, C.magenta}, {312, 405, 23, C.cyan}}
        for i, spot in ipairs(flareSpots) do
            local scale = flare(stage, spot[1], spot[2], spot[3], spot[4], 11)
            flares[i] = scale
        end

        local particles = {}
        for i = 1, low and 24 or 40 do
            local x = random:NextNumber(66, 934)
            local y = random:NextNumber(125, 485)
            local color = ({C.violet, C.magenta, C.cyan, C.white})[i % 4 + 1]
            local size = random:NextNumber(1.3, 3.5)
            local particle = frame(stage, "CrystalMote", UDim2.fromOffset(x, y), UDim2.fromOffset(size, size * (i % 3 == 0 and 2.1 or 1)), color, 0, 10)
            particle.AnchorPoint = Vector2.new(0.5, 0.5)
            particle.Rotation = 45
            local fade = paint(particle, "BackgroundTransparency", i % 4 == 0 and 0.85 or 0.52)
            particles[i] = {object = particle, fade = fade, x = x, y = y, phase = random:NextNumber(0, TWO_PI),
                speed = random:NextNumber(8, 20), drift = random:NextNumber(-6, 6)}
        end

        local loadArea = frame(stage, "Progress", UDim2.fromOffset(220, 514), UDim2.fromOffset(560, 64), C.black, 0, 20)
        local label = make("TextLabel", {
            Name = "Status", BackgroundTransparency = 1, Position = UDim2.fromOffset(0, 0), Size = UDim2.new(0.8, 0, 0, 22),
            Font = Enum.Font.GothamMedium, Text = "LOADING", TextSize = 13, TextColor3 = C.muted,
            TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21,
        }, loadArea)
        paint(label, "TextTransparency", 1, "bar")
        local percent = make("TextLabel", {
            Name = "Percentage", BackgroundTransparency = 1, Position = UDim2.new(1, -120, 0, -3), Size = UDim2.fromOffset(120, 26),
            Font = Enum.Font.GothamMedium, Text = "0%", TextSize = 20, TextColor3 = C.ice,
            TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 21,
        }, loadArea)
        paint(percent, "TextTransparency", 1, "bar")
        local track = frame(loadArea, "Track", UDim2.fromOffset(0, 32), UDim2.new(1, 0, 0, 5), Color3.fromRGB(28, 15, 45), 1, 21, "bar")
        make("UICorner", {CornerRadius = UDim.new(1, 0)}, track)
        local trackStroke = make("UIStroke", {Thickness = 1, Color = C.violet}, track)
        paint(trackStroke, "Transparency", 0.28, "bar")
        local barGlow = frame(loadArea, "BarGlow", UDim2.fromOffset(0, 29), UDim2.fromOffset(0, 11), C.violet, 0.12, 20, "bar")
        make("UICorner", {CornerRadius = UDim.new(1, 0)}, barGlow)
        local fill = frame(track, "Fill", UDim2.fromScale(0, 0), UDim2.fromScale(0, 1), C.white, 1, 22, "bar")
        make("UICorner", {CornerRadius = UDim.new(1, 0)}, fill)
        local fillGradient = gradient(fill, colorSequence({C.deep, C.violet, C.magenta, C.cyan, C.ice}))
        local fillLight = frame(fill, "FineHighlight", UDim2.fromScale(0, 0), UDim2.new(1, 0, 0, 1), C.white, 0.7, 23, "bar")
        gradient(fillLight, ColorSequence.new(C.white), SOFT_LINE)
        local headScale, head = flare(loadArea, 0, 34, 14, C.cyan, 24)
        local ticks, tickObjects = {}, {}
        for i = 0, 20 do
            local tick = frame(loadArea, "ProgressTick", UDim2.new(i / 20, 0, 0, 47), UDim2.fromOffset(1, i % 5 == 0 and 6 or 3), C.violet, 0, 21)
            ticks[i + 1] = paint(tick, "BackgroundTransparency", 0.44, "bar")
            tickObjects[i + 1] = tick
        end

        local currentScale, trackY, trackHeight = 1, 32, 5
        local function layout()
            local size = backdrop.AbsoluteSize
            if size.X < 1 or size.Y < 1 then
                local camera = workspace.CurrentCamera
                size = camera and camera.ViewportSize or Vector2.new(1280, 720)
            end
            local margin = math.max(12, math.min(26, size.Y * 0.035))
            border.Position = UDim2.fromOffset(margin, margin)
            border.Size = UDim2.new(1, -margin * 2, 1, -margin * 2)
            currentScale = math.max(0.1, math.min((size.X - margin * 2 - 18) / 1000, (size.Y - margin * 2 - 12) / 620, 1.8))
            stageScale.Scale = currentScale
            label.TextSize = math.max(13, 10 / currentScale)
            percent.TextSize = math.max(20, 13 / currentScale)
            label.Size = UDim2.new(0.8, 0, 0, math.max(22, 15 / currentScale))
            percent.Size = UDim2.fromOffset(120, math.max(26, 18 / currentScale))
            trackY, trackHeight = math.max(32, 22 / currentScale), math.max(5, 2 / currentScale)
            track.Position, track.Size = UDim2.fromOffset(0, trackY), UDim2.new(1, 0, 0, trackHeight)
            barGlow.Position = UDim2.fromOffset(0, trackY - 3)
            for i, tick in ipairs(tickObjects) do
                tick.Position = UDim2.new((i - 1) / 20, 0, 0, trackY + math.max(15, 7 / currentScale))
            end
            local w, h = size.X - margin * 2, size.Y - margin * 2
            -- Termina el degradado antes del area negra del logo. Asi su fondo
            -- se funde con la pantalla y no aparece un rectangulo alrededor.
            local sideDepth = math.max(8, math.min(w * 0.20, (size.X / 2 - 450 * currentScale - margin) * 0.86))
            local topDepth = math.max(8, math.min(h * 0.22, (size.Y / 2 - 263.25 * currentScale - margin) * 0.86))
            local bottomDepth = math.max(8, math.min(h * 0.22, (size.Y / 2 - 149.25 * currentScale - margin) * 0.86))
            edgeFrames[1].Size = UDim2.new(0, sideDepth, 1, 0)
            edgeFrames[2].Position, edgeFrames[2].Size = UDim2.new(1, -sideDepth, 0, 0), UDim2.new(0, sideDepth, 1, 0)
            edgeFrames[3].Size = UDim2.new(1, 0, 0, topDepth)
            edgeFrames[4].Position, edgeFrames[4].Size = UDim2.new(0, 0, 1, -bottomDepth), UDim2.new(1, 0, 0, bottomDepth)
            corners[1].Position, corners[1].Rotation = UDim2.fromOffset(0, 0), 0
            corners[2].Position, corners[2].Rotation = UDim2.fromOffset(w - 80, 0), 90
            corners[3].Position, corners[3].Rotation = UDim2.fromOffset(w - 80, h - 80), 180
            corners[4].Position, corners[4].Rotation = UDim2.fromOffset(0, h - 80), 270
        end
        S.connections[#S.connections + 1] = backdrop:GetPropertyChangedSignal("AbsoluteSize"):Connect(layout)
        layout()

        local function alive() return S.alive end
        local function useImage(uri, crop)
            local image = make("ImageLabel", {
                Name = "OriginalLogo", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
                Image = uri, ImageTransparency = 1, ScaleType = Enum.ScaleType.Fit, ZIndex = 7,
            }, logo)
            if crop then
                image.ImageRectOffset = Vector2.new(0, 96)
                image.ImageRectSize = Vector2.new(1536, 704)
            end
            local done, loaded = false, false
            task.spawn(function()
                local success = pcall(function()
                    ContentProvider:PreloadAsync({image})
                end)
                loaded, done = success and image.IsLoaded, true
            end)
            local deadline = os.clock() + 2
            while S.alive and not done and os.clock() < deadline do task.wait() end
            if S.alive and loaded then
                paint(image, "ImageTransparency", 1, "logo")
                fallback.Visible = false
                return true
            end
            image:Destroy()
            return false
        end

        local function installLogo()
            local asset = tostring(CONFIG.LogoAssetId or "")
            if asset ~= "" and asset ~= "0" then
                if asset:match("^%d+$") then asset = "rbxassetid://" .. asset end
                if useImage(asset, false) then return "asset" end
            end
            if not S.alive then return "cancelled" end
            local customAsset = getcustomasset or getsynasset
            if type(writefile) == "function" and type(customAsset) == "function" then
                local success, uri = pcall(function()
                    local bytes = base64Decode(loadOriginalBytes(), alive)
                    local path = "HzReyzn_Loading_Logo_bf6e8432.jpg"
                    writefile(path, buffer.tostring(bytes))
                    return customAsset(path)
                end)
                if success and type(uri) == "string" and S.alive and useImage(uri, true) then return "original" end
            end
            if not S.alive then return "cancelled" end
            local first
            local supported = pcall(function()
                first = AssetService:CreateEditableImage({Size = Vector2.new(768, 704)})
                assert(first, "EditableImage memory unavailable")
            end)
            if supported and first then
                S.images[#S.images + 1] = first
                local success, why = pcall(function()
                    local second = AssetService:CreateEditableImage({Size = Vector2.new(768, 704)})
                    assert(second, "EditableImage memory unavailable")
                    S.images[#S.images + 1] = second
                    local tiles, width, height = decodeLogoTiles(loadPixelBytes(), alive)
                    if not S.alive then return end
                    for i, editable in ipairs({first, second}) do
                        editable:WritePixelsBuffer(Vector2.zero, Vector2.new(width, height), tiles[i])
                        local image = make("ImageLabel", {
                            Name = "OriginalLogoTile" .. i, BackgroundTransparency = 1,
                            Position = UDim2.fromScale((i - 1) / 2, 0), Size = UDim2.fromScale(0.5, 1),
                            ImageContent = Content.fromObject(editable), ScaleType = Enum.ScaleType.Stretch,
                            ImageTransparency = 1, ZIndex = 7,
                        }, logo)
                        paint(image, "ImageTransparency", 1, "logo")
                    end
                    fallback.Visible = false
                end)
                if success and S.alive then return "pixels" end
                if S.alive then warn("HzReyzn: no se pudo preparar EditableImage: " .. tostring(why)) end
                for _, editable in ipairs(S.images) do pcall(function() editable:Destroy() end) end
                table.clear(S.images)
            end
            if S.alive then
                warn("HzReyzn: titulo de respaldo activo. Para ver tu imagen exacta, configura LogoAssetId con su ID de Roblox.")
            end
            return "fallback"
        end

        S.logoMode = installLogo()
        if not S.alive then return end
        if CONFIG.RemoveDefaultRobloxLoading then
            pcall(function() game:GetService("ReplicatedFirst"):RemoveDefaultLoadingScreen() end)
        end
        gui.Enabled = true
        layout()
        local startTime, lastPercent, lastEffects = os.clock(), -1, -1
        local duration = math.max(0.1, tonumber(CONFIG.Duration) or 5)
        local fadeOut = math.max(0.1, tonumber(CONFIG.FadeOut) or 0.95)

        local function update()
            if not S.alive then return end
            local t = os.clock() - startTime
            S.time = t
            local exitAmount = smooth((t - duration) / fadeOut)
            local visible = 1 - exitAmount
            local channels = {
                back = smooth(t / 0.6) * visible,
                frame = smooth((t - 0.10) / 0.95) * visible,
                fx = smooth((t - 0.25) / 0.95) * visible,
                logo = smooth((t - 0.20) / 1.05) * visible,
                bar = smooth((t - 0.52) / 0.75) * visible,
            }
            local progress = math.clamp(t / duration, 0, 1)
            local number = math.floor(progress * 100 + 0.00001)
            if number ~= lastPercent then
                percent.Text = tostring(number) .. "%"
                lastPercent = number
                if number == 100 then label.Text, label.TextColor3 = "READY", C.ice end
            end
            fill.Size = UDim2.fromScale(progress, 1)
            barGlow.Size = UDim2.new(progress, 0, 0, 11)
            head.Position = UDim2.new(progress, 0, 0, trackY + trackHeight / 2)
            head.Visible = progress > 0.008
            headScale.Scale = 0.8 + 0.14 * math.sin(t * 2.4)
            logoScale.Scale = 0.968 + 0.032 * smooth((t - 0.2) / 1.15) - exitAmount * 0.012
            logo.Position = UDim2.fromOffset(500, 253 + 11 * (1 - smooth((t - 0.2) / 1.15)) - exitAmount * 5)

            if t - lastEffects >= (low and 1 / 30 or 1 / 60) then
                lastEffects = t
                perimeterGradient.Rotation = 28 + t * 12
                fillGradient.Offset = Vector2.new(math.sin(t * 0.8) * 0.12, 0)
                auraScale.Scale = 1 + math.sin(t * 1.8) * 0.022
                for i, entry in ipairs(edgeGlows) do entry.multiplier = 0.87 + 0.13 * math.sin(t * 1.6 + i) end
                for i, scale in ipairs(flares) do scale.Scale = 0.76 + 0.24 * (0.5 + 0.5 * math.sin(t * 2.1 + i * 1.8)) end
                for i, entry in ipairs(ticks) do entry.multiplier = (i - 1) / 20 <= progress and 1 or 0.28 end
                for _, p in ipairs(particles) do
                    local age = (t * p.speed + p.phase * 38) % 350
                    local y = p.y - age * 0.19
                    p.object.Position = UDim2.fromOffset(p.x + math.sin(t * 0.42 + p.phase) * 8 + math.sin(t * 0.8) * p.drift, y)
                    p.object.Rotation = 45 + math.sin(t * 0.6 + p.phase) * 24
                    p.fade.multiplier = (0.35 + 0.65 * math.sin(t * 1.3 + p.phase) ^ 2) * math.sin(age / 350 * math.pi)
                end
                for orbit, items in ipairs(orbits) do
                    local spin = t * (orbit == 1 and 0.34 or -0.27) + orbit * 2.2
                    local tilt = orbit == 1 and -0.16 or 0.16
                    local function point(angle)
                        local x, y = math.cos(angle) * (orbit == 1 and 458 or 442), math.sin(angle) * (orbit == 1 and 162 or 152)
                        return 500 + x * math.cos(tilt) - y * math.sin(tilt), 266 + x * math.sin(tilt) + y * math.cos(tilt)
                    end
                    for i, object in ipairs(items) do
                        local a = spin + i / #items * 1.40
                        local x1, y1 = point(a)
                        local x2, y2 = point(a + 1.4 / #items * 0.88)
                        local dx, dy = x2 - x1, y2 - y1
                        object.Position = UDim2.fromOffset((x1 + x2) / 2, (y1 + y2) / 2)
                        object.Size = UDim2.fromOffset(math.sqrt(dx * dx + dy * dy), orbit == 1 and 1.35 or 0.9)
                        object.Rotation = math.deg(math.atan2(dy, dx))
                    end
                end
                local size = border.AbsoluteSize
                local w, h = size.X, size.Y
                local perimeterLength = 2 * (w + h)
                if perimeterLength > 0 then
                    for i, traveller in ipairs(travellers) do
                        local distance = (t * perimeterLength * 0.10 + (i - 1) * perimeterLength * 0.5) % perimeterLength
                        local x, y
                        if distance < w then x, y = distance, 1
                        elseif distance < w + h then x, y = w - 1, distance - w
                        elseif distance < w * 2 + h then x, y = w - (distance - w - h), h - 1
                        else x, y = 1, h - (distance - w * 2 - h) end
                        traveller.group.Position = UDim2.fromOffset(x, y)
                    end
                end
            end
            for _, entry in ipairs(S.fades) do
                local alpha = 1 - entry.opacity * entry.multiplier * channels[entry.channel]
                if math.abs(alpha - entry.last) > 0.0005 then
                    entry.object[entry.property] = math.clamp(alpha, 0, 1)
                    entry.last = alpha
                end
            end
            if t >= duration + fadeOut then cleanup(true) end
        end

        update()
        S.connections[#S.connections + 1] = RunService.RenderStepped:Connect(function()
            local success, why = pcall(update)
            if not success then
                warn("HzReyzn loading: " .. tostring(why))
                cleanup(false)
            end
        end)
        while S.alive do task.wait() end
    end, debug.traceback)

    if not ok then
        if S.alive then warn("HzReyzn loading: " .. tostring(errorMessage)) end
        cleanup(false)
    end
    if S.completed and type(CONFIG.OnComplete) == "function" then
        local success, why = pcall(CONFIG.OnComplete)
        if not success then warn("HzReyzn OnComplete: " .. tostring(why)) end
    end
    return S.completed
end

-- BEGIN EMBEDDED IMAGE. Conserva este bloque para mantener tu logo integrado.
loadOriginalBytes = function()
    return ""
end

loadPixelBytes = function()
    return ""
end
-- END EMBEDDED IMAGE.

play()
